function setAtPath(target: JsonMap, path: string[], value: any) {
  let cursor: JsonMap = target;
  for (let index = 0; index < path.length - 1; index += 1) {
    cursor[path[index]] = cursor[path[index]] ?? {};
    cursor = cursor[path[index]];
  }
  cursor[path[path.length - 1]] = value;
}

function listToCSV(value: any) {
  return Array.isArray(value) ? value.join(", ") : "";
}

function csvToList(value: string) {
  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function csvToNumberList(value: string) {
  return csvToList(value)
    .map((item) => Number(item))
    .filter((item) => Number.isFinite(item) && item > 0);
}

function formatMicros(value: number | undefined, currency = "USD") {
  const amount = (value || 0) / 1_000_000;
  return `${currency} ${amount.toFixed(6)}`;
}

function statusTone(status?: string) {
  switch ((status || "").toLowerCase()) {
    case "ready":
    case "ok":
    case "ack":
    case "passed":
    case "fail_closed":
      return "border-emerald-200 bg-emerald-50 text-emerald-800";
    case "blocked":
    case "error":
      return "border-red-200 bg-red-50 text-red-800";
    case "disabled":
    case "skipped":
      return "border-gray-200 bg-gray-50 text-gray-700";
    default:
      return "border-amber-200 bg-amber-50 text-amber-800";
  }
}
function mapToLines(value: any) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return "";
  }
  return Object.entries(value)
    .map(([key, mapped]) => `${key}=${String(mapped)}`)
    .join("\n");
}

function linesToMap(value: string) {
  return value
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .reduce((next: JsonMap, line) => {
      const [key, ...rest] = line.split("=");
      const mapped = rest.join("=").trim();
      if (key.trim() && mapped) {
        next[key.trim()] = mapped;
      }
      return next;
    }, {});
}

function TextField({
  label,
  value,
  onChange,
  type = "text",
  placeholder,
}: {
  label: string;
  value: string | number;
  onChange: (value: string) => void;
  type?: string;
  placeholder?: string;
}) {
  return (
    <label className="block text-sm font-medium text-gray-700">
      <span>{label}</span>
      <input
        type={type}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        placeholder={placeholder}
        className="mt-1 w-full rounded-md border border-gray-300 px-3 py-2"
      />
    </label>
  );
}

function SelectField({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: Option[];
  onChange: (value: string) => void;
}) {
  return (
    <label className="block text-sm font-medium text-gray-700">
      <span>{label}</span>
      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="mt-1 w-full rounded-md border border-gray-300 px-3 py-2"
      >
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </label>
  );
}

function ToggleField({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange: (value: boolean) => void;
}) {
  return (
    <label className="flex items-center gap-3 rounded-md border border-gray-200 px-3 py-2 text-sm text-gray-700">
      <input
        type="checkbox"
        checked={checked}
        onChange={(event) => onChange(event.target.checked)}
        className="h-4 w-4"
      />
      <span>{label}</span>
    </label>
  );
}

